package com.bigjaysstowing.towguide;
import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.os.Handler;import android.os.Looper;import android.util.Base64;
import com.getcapacitor.JSObject;import com.getcapacitor.Plugin;import com.getcapacitor.PluginCall;import com.getcapacitor.PluginMethod;import com.getcapacitor.annotation.CapacitorPlugin;
import com.google.android.gms.common.moduleinstall.ModuleInstall;import com.google.android.gms.common.moduleinstall.ModuleInstallClient;import com.google.android.gms.common.moduleinstall.ModuleInstallRequest;
import com.google.mlkit.vision.barcode.common.Barcode;import com.google.mlkit.vision.codescanner.GmsBarcodeScanner;import com.google.mlkit.vision.codescanner.GmsBarcodeScannerOptions;import com.google.mlkit.vision.codescanner.GmsBarcodeScanning;
import com.google.mlkit.vision.text.TextRecognition;import com.google.mlkit.vision.text.TextRecognizer;import com.google.mlkit.vision.text.latin.TextRecognizerOptions;import com.google.mlkit.vision.common.InputImage;
@CapacitorPlugin(name="NativeVinScanner") public class NativeVinScannerPlugin extends Plugin {
 private static final long CHECK_MS=750L;private static final int MAX_CHECKS=80;
 @PluginMethod public void scanBarcode(PluginCall call){GmsBarcodeScannerOptions options=new GmsBarcodeScannerOptions.Builder().setBarcodeFormats(Barcode.FORMAT_ALL_FORMATS).enableAutoZoom().build();GmsBarcodeScanner scanner=GmsBarcodeScanning.getClient(getContext(),options);ModuleInstallClient installer=ModuleInstall.getClient(getContext());installer.areModulesAvailable(scanner).addOnSuccessListener(getActivity(),a->{if(a.areModulesAvailable()){launch(scanner,call);return;}ModuleInstallRequest req=ModuleInstallRequest.newBuilder().addApi(scanner).build();installer.installModules(req).addOnSuccessListener(getActivity(),r->{if(r.areModulesAlreadyInstalled())launch(scanner,call);else waitForModule(installer,scanner,call,0);}).addOnFailureListener(getActivity(),e->call.reject("Could not install Google's barcode scanner module: "+e.getMessage(),e));}).addOnFailureListener(getActivity(),e->call.reject("Could not check barcode scanner availability: "+e.getMessage(),e));}
 private void waitForModule(ModuleInstallClient c,GmsBarcodeScanner s,PluginCall call,int n){if(n>=MAX_CHECKS){call.reject("Google's barcode scanner module did not finish installing. Update Google Play services and retry.");return;}new Handler(Looper.getMainLooper()).postDelayed(()->c.areModulesAvailable(s).addOnSuccessListener(getActivity(),a->{if(a.areModulesAvailable())launch(s,call);else waitForModule(c,s,call,n+1);}).addOnFailureListener(getActivity(),e->call.reject("Could not verify scanner installation: "+e.getMessage(),e)),CHECK_MS);}
 private void launch(GmsBarcodeScanner s,PluginCall call){s.startScan().addOnSuccessListener(getActivity(),b->{JSObject r=new JSObject();r.put("rawValue",b.getRawValue());r.put("format",b.getFormat());call.resolve(r);}).addOnCanceledListener(getActivity(),()->call.reject("Barcode scan cancelled.")).addOnFailureListener(getActivity(),e->call.reject("Barcode scanner failed: "+e.getMessage(),e));}
 @PluginMethod public void recognizeText(PluginCall call){String encoded=call.getString("imageBase64");if(encoded==null||encoded.trim().isEmpty()){call.reject("No image was supplied for recognition.");return;}TextRecognizer recognizer=TextRecognition.getClient(TextRecognizerOptions.DEFAULT_OPTIONS);try{byte[] bytes=Base64.decode(encoded,Base64.DEFAULT);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap==null){recognizer.close();call.reject("Selected photo could not be decoded.");return;}recognizer.process(InputImage.fromBitmap(bitmap,0)).addOnSuccessListener(getActivity(),t->{JSObject r=new JSObject();r.put("text",t.getText());call.resolve(r);}).addOnFailureListener(getActivity(),e->call.reject("Android text recognition failed: "+e.getMessage(),e)).addOnCompleteListener(task->{recognizer.close();bitmap.recycle();});}catch(Exception e){recognizer.close();call.reject("Could not prepare photo: "+e.getMessage(),e);}}
}